fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2:
    if n < 2 {
        return false;
    }

    // We check all divisors k from 2 up to n-1:
    // Loop invariant:
    // - n >= 2
    // - divisor (k) is always in [2, n]
    // - for all j in [2, k), n % j != 0
    //
    // Termination measure: n - k, strictly decreases each iteration.
    let mut k = 2;
    while k < n {
        if n % k == 0 {
            // Found a divisor, so not prime:
            return false;
        }
        k += 1;
    }

    // No divisors found means n is prime per definition:
    true
}